import{H as e,V as t,et as n,j as r}from"./chunks/framework.DKIRGhFK.js";import{Bl as i,Gl as a,Hl as o,Kl as s,Rl as c,Ul as l,Vl as u,Wl as d,ql as f,zl as p}from"./chunks/assets.CDtaeP7d.js";var m=JSON.parse(`{"title":"配置优先级","description":"","frontmatter":{},"headers":[],"relativePath":"java/spring-boot/configuration-priority.md","filePath":"java/spring-boot/configuration-priority.md"}`),h={name:`java/spring-boot/configuration-priority.md`};function g(r,m,h,g,_,v){return n(),t(`div`,null,[...m[0]||=[e(`<h1 id="配置优先级" tabindex="-1">配置优先级 <a class="header-anchor" href="#配置优先级" aria-label="Permalink to “配置优先级”">​</a></h1><p>在我们前面的课程当中，我们已经讲解了SpringBoot项目当中支持的三类配置文件：</p><ul><li><p>application.properties</p></li><li><p>application.yml</p></li><li><p>application.yaml</p></li></ul><p>在SpringBoot项目当中，我们要想配置一个属性，可以通过这三种方式当中的任意一种来配置都可以，那么如果项目中同时存在这三种配置文件，且都配置了同一个属性，如：Tomcat端口号，到底哪一份配置文件生效呢？</p><ul><li>application.properties</li></ul><div class="language-Properties"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">Properties</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">server.port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=8081</span></span></code></pre></div><ul><li>application.yml</li></ul><div class="language-YAML"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">   port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8082</span></span></code></pre></div><ul><li>application.yaml</li></ul><div class="language-YAML"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">   port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8082</span></span></code></pre></div><p>我们启动SpringBoot程序，测试下三个配置文件中哪个Tomcat端口号生效：</p><ul><li>properties、yaml、yml三种配置文件同时存在。 配置好了，启动服务，测试一下：</li></ul><p><img src="`+f+`" alt="imagepng" width="1886" height="976"></p><p>properties、yaml、yml三种配置文件，优先级最高的是properties</p><ul><li>yaml、yml两种配置文件同时存在</li></ul><p><img src="`+s+`" alt="imagepng" width="1883" height="973"></p><p>yaml、yml 两种配置文件，优先级最高的是yml。</p><p><strong>配置文件优先级排名（从高到低）：</strong></p><ol><li><p>properties配置文件</p></li><li><p>yml配置文件</p></li><li><p>yaml配置文件</p></li></ol><p><strong>注意事项：</strong>虽然springboot支持多种格式配置文件，但是在项目开发时，推荐统一使用一种格式的配置。（yml是主流）</p><p>在SpringBoot项目当中除了以上3种配置文件外，SpringBoot为了增强程序的扩展性，除了支持配置文件的配置方式以外，还支持另外两种常见的配置方式：</p><ol><li>Java系统属性配置 （格式： -Dkey=value）</li></ol><div class="language-YAML"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-Dserver.port=9000</span></span></code></pre></div><ol start="2"><li>命令行参数 （格式：--key=value）</li></ol><div class="language-YAML"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">--server.port=10010</span></span></code></pre></div><p>那在idea当中运行程序时，如何来指定Java系统属性和命令行参数呢？</p><ul><li>编辑启动程序的配置信息</li></ul><p><img src="`+a+`" alt="imagepng" width="1923" height="240"></p><p>打开之后，选择 <code>Modify options</code> , 选择 <code>Add VM options</code>, <code>Program arguments</code></p><p><img src="`+d+`" alt="imagepng" width="1501" height="784"></p><p>重启服务，同时配置Tomcat端口(application.properties、系统属性、命令行参数)，测试哪个Tomcat端口号生效：</p><p><img src="`+l+`" alt="imagepng" width="1919" height="847"></p><p>说明，命令行参数的优先级时最高的，同时配置的情况下，命令行参数的配置项生效。</p><p>删除命令行参数配置，重启SpringBoot服务：</p><p><img src="`+o+`" alt="imagepng" width="1279" height="784"></p><p><img src="`+u+`" alt="imagepng" width="1919" height="955"></p><p><strong>五种配置方式的优先级：</strong> 命令行参数 &gt; 系统属性参数 &gt; properties参数 &gt; yml参数 &gt; yaml参数</p><p>思考：如果项目已经打包上线了，这个时候我们又如何来设置Java系统属性和命令行参数呢？</p><div class="language-YAML"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">java -Dserver.port=9000 -jar XXXXX.jar --server.port=10010</span></span></code></pre></div><p>下面我们来演示下打包程序运行时指定Java系统属性和命令行参数：</p><ol><li>执行maven打包指令package，把项目打成jar文件</li></ol><p><img src="`+i+`" alt="imagepng" width="1747" height="860"></p><ol start="2"><li>使用命令：java -jar 方式运行jar文件程序。</li></ol><p>同时设置Java系统属性和命令行参数</p><p><img src="`+p+`" alt="imagepng" width="1607" height="748"></p><p>仅设置Java系统属性</p><p><img src="`+c+`" alt="imagepng" width="1608" height="749"></p><p><strong>注意事项：</strong></p><ul><li>Springboot项目进行打包时，需要引入插件 <code>spring-boot-maven-plugin</code> (基于官网骨架创建项目，会自动添加该插件)</li></ul><p>在SpringBoot项目当中，常见的属性配置方式有5种， 3种配置文件，加上2种外部属性的配置(Java系统属性、命令行参数)。通过以上的测试，我们也得出了优先级(从低到高)：</p><ul><li><p>application.yaml（忽略）</p></li><li><p>application.yml</p></li><li><p>application.properties</p></li><li><p>java系统属性（-Dxxx=xxx）</p></li><li><p>命令行参数（--xxx=xxx）</p></li></ul>`,51)]])}var _=r(h,[[`render`,g]]);export{m as __pageData,_ as default};